import { useState } from 'react';
import {
  JxCard,
  JxSteps,
  JxStep,
  JxFormField,
  JxInput,
  JxButton,
  JxStack,
  JxText,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationFormValues {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (values: RegistrationFormValues) => void;
}

const STEP_LABELS = ['Контакты', 'Адрес', 'Проверка'];

const INITIAL_VALUES: RegistrationFormValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  postalCode: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [values, setValues] = useState<RegistrationFormValues>(INITIAL_VALUES);

  const updateField = (field: keyof RegistrationFormValues) => (value: string) => {
    setValues((prev) => ({ ...prev, [field]: value }));
  };

  const isLastStep = currentStep === STEP_LABELS.length - 1;
  const isFirstStep = currentStep === 0;

  const handleNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(values);
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 'var(--jx-size-xl)' }}>
      <JxStack direction="column" gap="lg">
        <JxSteps activeStep={currentStep}>
          {STEP_LABELS.map((label, index) => (
            <JxStep key={label} label={label} completed={index < currentStep} />
          ))}
        </JxSteps>

        <JxDivider />

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Контактная информация</JxText>
            <JxFormField label="Полное имя" htmlFor="fullName">
              <JxInput
                id="fullName"
                value={values.fullName}
                onChange={(e) => updateField('fullName')(e.target.value)}
                placeholder="Иван Иванов"
              />
            </JxFormField>
            <JxFormField label="Email" htmlFor="email">
              <JxInput
                id="email"
                type="email"
                value={values.email}
                onChange={(e) => updateField('email')(e.target.value)}
                placeholder="name@example.com"
              />
            </JxFormField>
            <JxFormField label="Телефон" htmlFor="phone">
              <JxInput
                id="phone"
                type="tel"
                value={values.phone}
                onChange={(e) => updateField('phone')(e.target.value)}
                placeholder="+7 900 000-00-00"
              />
            </JxFormField>
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Адрес</JxText>
            <JxFormField label="Страна" htmlFor="country">
              <JxInput
                id="country"
                value={values.country}
                onChange={(e) => updateField('country')(e.target.value)}
                placeholder="Россия"
              />
            </JxFormField>
            <JxFormField label="Город" htmlFor="city">
              <JxInput
                id="city"
                value={values.city}
                onChange={(e) => updateField('city')(e.target.value)}
                placeholder="Москва"
              />
            </JxFormField>
            <JxFormField label="Улица и дом" htmlFor="street">
              <JxInput
                id="street"
                value={values.street}
                onChange={(e) => updateField('street')(e.target.value)}
                placeholder="ул. Примерная, д. 1"
              />
            </JxFormField>
            <JxFormField label="Почтовый индекс" htmlFor="postalCode">
              <JxInput
                id="postalCode"
                value={values.postalCode}
                onChange={(e) => updateField('postalCode')(e.target.value)}
                placeholder="123456"
              />
            </JxFormField>
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Проверка данных</JxText>
            <JxCard variant="subtle" className="jx-p-md">
              <JxStack direction="column" gap="sm">
                <JxText variant="body-sm" color="secondary">Полное имя</JxText>
                <JxText variant="body-md">{values.fullName || '—'}</JxText>
                <JxDivider />
                <JxText variant="body-sm" color="secondary">Email</JxText>
                <JxText variant="body-md">{values.email || '—'}</JxText>
                <JxDivider />
                <JxText variant="body-sm" color="secondary">Телефон</JxText>
                <JxText variant="body-md">{values.phone || '—'}</JxText>
                <JxDivider />
                <JxText variant="body-sm" color="secondary">Адрес</JxText>
                <JxText variant="body-md">
                  {[values.country, values.city, values.street, values.postalCode]
                    .filter(Boolean)
                    .join(', ') || '—'}
                </JxText>
              </JxStack>
            </JxCard>
          </JxStack>
        )}

        <JxDivider />

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={handleBack} disabled={isFirstStep}>
            Назад
          </JxButton>
          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={handleNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

